from modele import *

chapitre(7,'grandeurs','Grandeurs quotients et conversions','2 · Proportionnalité et fonctions',
'Durées · Vitesses · Débits · Masses volumiques · Unités',
['Convertir les unités adaptées à une situation.','Calculer avec une vitesse, un débit ou une masse volumique.','Contrôler les unités et l’ordre de grandeur d’un résultat.'],['Grandeurs quotients rencontrées en Quatrième, proportionnalité et unités.'],[
r'''\essSection{1}{Choisir et convertir les unités}
\begin{propriete}Pour les longueurs, $1\text{ m}=100\text{ cm}$. Pour les aires, $1\text{ m}^2=10000\text{ cm}^2$ ; pour les volumes, $1\text{ m}^3=10^6\text{ cm}^3$. Le facteur de conversion est mis au carré ou au cube.\end{propriete}
\begin{propriete}$1\text{ L}=1\text{ dm}^3$, $1\text{ mL}=1\text{ cm}^3$ et $1\text{ m}^3=1000\text{ L}$. Une tonne vaut 1000 kg. Une heure vaut 60 min, soit 3600 s.\end{propriete}
\begin{exemple}$2{,}4\text{ h}=2\text{ h}+0{,}4\times60\text{ min}=2\text{ h }24\text{ min}$. À l’inverse, 2 h 15 min valent $2+15/60=2{,}25$ h.\end{exemple}
\begin{attention}1 h 30 min n’est pas 1,30 h. De même, multiplier par 100 pour convertir une aire en m$^2$ vers des cm$^2$ est incorrect : le facteur est 10000.\end{attention}
\begin{savoirfaire}[Contrôler la cohérence]Nommer la grandeur et son unité à chaque étape. Une aire ne s’exprime pas en mètres, une durée ne s’exprime pas en kilomètres. Donner un ordre de grandeur avant de conclure.\end{savoirfaire}''',
r'''\essSection{2}{Des grandeurs quotients}
\begin{definition}Une grandeur quotient est le quotient de deux grandeurs. Une vitesse moyenne vaut $v=d/t$, avec $t>0$. Un débit volumique est un volume par unité de temps : $q=V/t$. Une masse volumique est une masse par unité de volume : $\rho=m/V$.\end{definition}
\begin{exemple}$72\text{ km/h}=72000/3600=20\text{ m/s}$. Pour convertir des km/h en m/s, diviser par 3,6 ; pour l’opération inverse, multiplier par 3,6.\end{exemple}
\begin{savoirfaire}[Une chaîne de calculs]On peut utiliser $d=vt$ et $t=d/v$ pour $v>0$. Pour remplir 600 L à un débit de 15 L/min, la durée est $600/15=40$ min. À débit constant, doubler le volume double la durée : la durée est proportionnelle au volume.\end{savoirfaire}
\begin{attention}La moyenne de deux vitesses n’est pas généralement la vitesse moyenne d’un trajet. Les durées passées à chaque vitesse comptent : diviser la distance totale par la durée totale.\end{attention}
Ces grandeurs, étudiées en Quatrième, interviennent souvent dans les problèmes du brevet et dans les autres disciplines.'''],[
E('Des longueurs et des aires',r"Convertir 3,8 km en mètres, 0,42 m$^2$ en cm$^2$ et 6500 cm$^2$ en m$^2$.",r"On obtient $\res{3800\text{ m}}$, $\res{4200\text{ cm}^2}$ et $\res{0{,}65\text{ m}^2}$. Les deux dernières conversions utilisent le facteur 10000.","Distinguer le facteur des longueurs de celui des aires.","assert Rational('3.8')*1000==3800 and Rational('.42')*10000==4200 and Rational(6500,10000)==Rational('.65')"),
E('Volumes et contenances',r"Convertir 2,7 m$^3$ en litres et 450 mL en cm$^3$ puis en litres.",r"$2{,}7\text{ m}^3=\res{2700\text{ L}}$. Comme un mL est un cm$^3$, 450 mL valent $\res{450\text{ cm}^3}$, soit $\res{0{,}45\text{ L}}$.","Utiliser les équivalences entre volumes et contenances.","assert Rational('2.7')*1000==2700 and Rational(450,1000)==Rational('.45')"),
E('Une durée décimale',r"Écrire 1,75 h en heures et minutes ; écrire 2 h 42 min en heures décimales.",r"$0{,}75\times60=45$, donc $\res{1\text{ h }45\text{ min}}$. Inversement, $42/60=0{,}7$, donc $\res{2{,}7\text{ h}}$.","Convertir la partie d’heure avec 60.","assert Rational(75,100)*60==45 and 2+Rational(42,60)==Rational(27,10)"),
E('Une vitesse moyenne',r"Un trajet de 150 km est parcouru en 2 h 30 min. Calculer la vitesse moyenne.",r"La durée vaut 2,5 h. La vitesse moyenne est $150/2{,}5=\res{60\text{ km/h}}$. Diviser par 2,30 aurait mal traduit les minutes.","Mettre toute la durée dans l’unité choisie.","assert 150/Rational(5,2)==60"),
E('Un débit',r"Un robinet fournit 84 L en 7 minutes, à débit constant. Donner son débit et le volume en 25 minutes.",r"Le débit est $84/7=\res{12\text{ L/min}}$. Le volume en 25 minutes vaut $12\times25=\res{300\text{ L}}$.","Calculer le volume d’une minute.","assert 84//7==12 and 12*25==300"),
E('Convertir une vitesse',r"Convertir 90 km/h en m/s et 12 m/s en km/h.",r"$90/3{,}6=\res{25\text{ m/s}}$. Dans l’autre sens, $12\times3{,}6=\res{43{,}2\text{ km/h}}$. Un contrôle direct emploie 1000 m et 3600 s.","Revenir aux unités de base pour justifier le facteur 3,6.","assert Rational(90)/Rational('3.6')==25 and 12*Rational('3.6')==Rational('43.2')"),
E('Le temps de réaction',r"Une voiture roule à 54 km/h. Le conducteur met 0,8 s avant de commencer à freiner. Quelle distance parcourt-elle pendant cette réaction ?",r"La vitesse vaut $54/3{,}6=15$ m/s. La distance pendant 0,8 s est $15\times0{,}8=\res{12\text{ m}}$. Ce calcul ne comprend pas la distance de freinage.","Séparer la réaction du freinage.","assert Rational(54)/Rational('3.6')*Rational('.8')==12"),
E('Une masse volumique',r"Un matériau a une masse volumique de 2,5 g/cm$^3$. Un bloc occupe 360 cm$^3$. Calculer sa masse en grammes puis en kilogrammes.",r"La masse vaut $\rho V=2{,}5\times360=\res{900\text{ g}}$, soit $\res{0{,}9\text{ kg}}$. Les cm$^3$ du volume sont cohérents avec ceux du dénominateur de la masse volumique.","Multiplier le volume par la masse d’une unité de volume.","assert Rational('2.5')*360==900 and Rational(900,1000)==Rational('.9')"),
E('Une consommation électrique',r"Un appareil de puissance constante 1,2 kW fonctionne pendant 45 minutes. Calculer l’énergie en kWh. Le kWh coûte 0,24 € dans le modèle proposé. Calculer le coût.",r"45 minutes valent 0,75 h. L’énergie vaut $1{,}2\times0{,}75=\res{0{,}9\text{ kWh}}$. Le coût vaut $0{,}9\times0{,}24=\res{0{,}216\text{ €}}$, soit 0,22 € au centime. Le tarif est une donnée de l’exercice.","Convertir la durée avant de calculer l’énergie.","assert Rational('1.2')*Rational(45,60)==Rational('.9') and Rational('.9')*Rational('.24')==Rational('.216')"),
E('Un téléchargement',r"Un fichier de 2,4 Go est téléchargé à un débit constant de 40 Mo/s. Écrire ces données en octets avec des puissances de 10, puis calculer la durée du téléchargement.",r"$2{,}4\text{ Go}=2{,}4\times10^9$ octets et $40\text{ Mo/s}=4\times10^7$ octets par seconde. La durée vaut $2{,}4\times10^9/(4\times10^7)=0{,}6\times10^2=\res{60\text{ s}}$, soit une minute.","Remplacer les préfixes par des puissances de 10 avant de diviser.","assert Rational('2.4')*10**9/(4*10**7)==60"),
E('Aller et retour',r"Un cycliste parcourt 12 km à 18 km/h, puis revient sur 12 km à 12 km/h. Calculer sa vitesse moyenne sur l’aller-retour.",r"L’aller dure $12/18=2/3$ h ; le retour dure 1 h. Le total est 24 km en $5/3$ h. La vitesse moyenne vaut $24/(5/3)=\res{14{,}4\text{ km/h}}$. La moyenne 15 km/h des deux vitesses ne convient pas, car les durées diffèrent.","Additionner distances et durées avant de diviser.","assert 24/(Rational(12,18)+Rational(12,12))==Rational('14.4')"),
E('Deux robinets',r"Un premier robinet remplit seul une cuve en 30 min, un second en 45 min. Ils fonctionnent ensemble avec des débits constants et indépendants. Quelle durée pour remplir la cuve ?",r"En une minute, ils remplissent respectivement $1/30$ et $1/45$ de la cuve. Ensemble : $1/30+1/45=1/18$. Le remplissage prend donc $\res{18\text{ min}}$. Additionner les deux durées aurait ignoré l’addition des débits.","Additionner les fractions de cuve remplies par minute.","assert 1/(Rational(1,30)+Rational(1,45))==18"),
E('Choisir assez de peinture',r"Un mur rectangulaire mesure 5 m sur 2,6 m. Une ouverture de 2 m$^2$ n’est pas peinte. Deux couches sont prévues. Un litre couvre 8 m$^2$ par couche. Les pots contiennent 2,5 L. Combien de pots acheter ?",r"L’aire à peindre est $5\times2{,}6-2=11$ m$^2$. Les deux couches représentent 22 m$^2$ à couvrir, donc $22/8=2{,}75$ L. Un pot ne suffit pas ; il faut $\res{2\text{ pots}}$. On n’arrondit pas le besoin au-dessous.","Calculer l’aire utile, les couches, puis l’achat entier.","assert (5*Rational('2.6')-2)*2/8==Rational('2.75') and ceil(Rational('2.75')/Rational('2.5'))==2"),
E('Une fuite discrète',r"Une fuite laisse tomber 2 gouttes par seconde. On modélise une goutte par 0,05 mL. Quel volume d’eau est perdu en une journée ? En 30 jours ?",r"Le débit est 0,1 mL/s. Une journée compte 86400 s, d’où $8640$ mL, soit $\res{8{,}64\text{ L}}$. En 30 jours : $\res{259{,}2\text{ L}}$. Le résultat dépend du volume de goutte choisi dans le modèle.","Construire le débit puis multiplier par la durée totale.","assert 2*Rational('.05')*86400/1000==Rational('8.64') and Rational('8.64')*30==Rational('259.2')"),
E('Une livraison de gravier',r"Une allée de 12 m sur 1,5 m reçoit une couche uniforme de gravier de 6 cm. La masse volumique apparente est 1,6 tonne/m$^3$. Un camion peut emporter 1,5 tonne. Combien de voyages au minimum ?",r"On convertit l’épaisseur en 0,06 m. Le volume vaut $12\times1{,}5\times0{,}06=1{,}08$ m$^3$. La masse est $1{,}08\times1{,}6=1{,}728$ tonne. Elle dépasse 1,5 tonne : $\res{2\text{ voyages}}$ suffisent et un seul est impossible.","Employer les mètres pour les trois dimensions du volume.","assert 12*Rational('1.5')*Rational('.06')*Rational('1.6')==Rational('1.728') and ceil(Rational('1.728')/Rational('1.5'))==2")
],reperes=['Conversions de longueurs, aires et volumes','Durées et vitesses moyennes','Débits et masses volumiques','Grandeurs quotients et contrôle des unités'])

valeurs8=tableau(['$x$','$-2$','$0$','$1$','$3$'],[['$f(x)$','$5$','$1$','$-1$','$1$']])
chapitre(8,'fonctions','Fonctions, images et fonction carré','2 · Proportionnalité et fonctions',
r'Formules · Tableaux · Courbes · Images · Antécédents · $x\mapsto x^2$',
['Utiliser le vocabulaire et les notations des fonctions.','Passer d’une formule à un tableau ou à une courbe.','Représenter la fonction carré et résoudre graphiquement $x^2=a$.'],['Repérage, substitution dans une expression et racine carrée.'],[
r'''\essSection{1}{Une entrée et une image}
\begin{definition}Une fonction associe à chaque nombre autorisé une seule image. On écrit $f(x)$ pour l’image de $x$ par $f$, et $f:x\mapsto x^2+1$ pour décrire la fonction. Si $f(3)=8$, 8 est l’image de 3 et 3 est un antécédent de 8. Un nombre peut avoir plusieurs antécédents, ou aucun.\end{definition}
\begin{exemple}Pour $f(x)=x^2+1$, $f(-2)=5$. Les nombres $-2$ et 2 sont deux antécédents de 5. Aucun nombre n’a pour image 0, car $x^2+1\ge1$.\end{exemple}
\begin{savoirfaire}[Trois représentations]Une formule permet de calculer toute image ; un tableau de valeurs n’en donne que quelques-unes ; une courbe rassemble les points de coordonnées $(x\,;f(x))$. Un point appartient à la courbe lorsque son ordonnée est l’image de son abscisse.\end{savoirfaire}
\begin{attention}$f(2)$ ne signifie pas $f\times2$. Ne pas échanger l’image et l’antécédent dans une phrase. Un tableau partiel ne permet pas d’inventer l’image d’une entrée non indiquée.\end{attention}
\begin{propriete}Comparer deux fonctions graphiquement revient à comparer leurs ordonnées pour une même abscisse. Les intersections correspondent aux entrées donnant la même image.\end{propriete}''',
r'''\essSection{2}{Lire une courbe et la fonction carré}
\begin{savoirfaire}[Lire une image ou des antécédents]Partir d’une abscisse, rejoindre la courbe verticalement, puis lire l’ordonnée. Pour chercher les antécédents d’un nombre, partir de cette ordonnée et repérer toutes les intersections horizontales avec la courbe. Une lecture graphique est souvent approchée.\end{savoirfaire}
\begin{definition}La fonction carré est la fonction $x\mapsto x^2$. Sa courbe, symétrique par rapport à l’axe des ordonnées, est une parabole qui passe par l’origine et reste au-dessus de l’axe des abscisses.\end{definition}
\begin{propriete}Résoudre graphiquement $x^2=a$, c’est chercher les abscisses des points d’intersection de la parabole avec la droite horizontale d’équation $y=a$ : deux points si $a>0$, un seul si $a=0$, aucun si $a<0$.\end{propriete}
\begin{savoirfaire}[Modéliser]Nommer la variable et son unité, exprimer la quantité cherchée, puis préciser les entrées possibles. Un nombre de billets est entier ; une longueur doit rester positive. Pour une cuve de base 12 m$^2$, le volume est $V(h)=12h$, pour $h$ compris entre 0 et la hauteur maximale.\end{savoirfaire}'''],[
E('Calculer des images',r"Pour $f:x\mapsto3x-4$, calculer $f(0)$, $f(2)$ et $f(-3)$.",r"On remplace $x$ : $\res{f(0)=-4}$, $\res{f(2)=2}$ et $\res{f(-3)=-13}$. Chaque entrée donne une seule image.","Substituer en gardant les parenthèses pour les négatifs.","assert [(3*x-4).subs(x,a) for a in [0,2,-3]]==[-4,2,-13]"),
E('Lire un tableau',r"À l’aide du tableau, donner $f(-2)$ et les antécédents de 1 qui y figurent."+valeurs8,r"À la colonne de $-2$, l’image est $\res5$. La valeur 1 apparaît sous les entrées 0 et 3 : les antécédents indiqués sont $\res{0\text{ et }3}$. Le tableau ne dit pas s’il en existe ailleurs.","Distinguer ce qui est connu dans le tableau et ce qui ne l’est pas.","assert [a for a,b in [(-2,5),(0,1),(1,-1),(3,1)] if b==1]==[0,3]"),
E('Traduire une phrase',r"Écrire avec une égalité : « 7 est l’image de $-1$ par $g$ ». Dire ensuite ce que signifie $g(4)=7$. Ces deux informations sont-elles compatibles ?",r"La première phrase s’écrit $\res{g(-1)=7}$. La deuxième signifie que 7 est l’image de 4, ou que 4 est un antécédent de 7. Elles sont compatibles : un nombre peut avoir plusieurs antécédents, mais une entrée n’a qu’une image.","Identifier le rôle de l’entrée et de la sortie.","assert -1!=4 and len({-1:7,4:7})==2"),
E('Un point sur une courbe',r"Pour $f(x)=x^2-2$, les points $A(3\,;7)$ et $B(-2\,;1)$ appartiennent-ils à la courbe ?",r"$f(3)=9-2=7$ : $\res{A\text{ appartient à la courbe}}$. $f(-2)=4-2=2\ne1$ : $\res{B\text{ n’y appartient pas}}$. Une lecture approximative ne remplace pas ces calculs.","Calculer l’image de chaque abscisse.","assert 3**2-2==7 and (-2)**2-2!=1"),
E('Un antécédent algébrique',r"Pour $h(x)=5x+2$, déterminer l’antécédent de 17.",r"On résout $5x+2=17$, d’où $5x=15$ et $\res{x=3}$. Vérification : $h(3)=17$. Le coefficient 5 non nul assure une seule solution.","Écrire l’égalité correspondant à l’image demandée.","assert solve(5*x+2-17,x)==[3]"),
E('Une formule et un programme',r"On choisit un nombre, on ajoute 3, puis on élève le résultat au carré. Donner la fonction obtenue et les images de 1 et $-3$.",r"La fonction est $\res{f:x\mapsto(x+3)^2}$. Ainsi $f(1)=16$ et $f(-3)=0$. Écrire $x^2+3$ n’aurait pas respecté l’ordre des instructions.","Traduire chaque étape avant de transformer l’expression.","assert (1+3)**2==16 and (-3+3)**2==0"),
E('Lire une ligne brisée',r"La courbe est formée des segments dessinés, avec les sommets sur les graduations indiquées. Lire $f(-1)$ et tous les antécédents de 1.",r"Le sommet d’abscisse $-1$ a pour ordonnée $\res3$. La droite horizontale d’ordonnée 1 rencontre la ligne aux abscisses $\res{-3,0,3}$. Sur le segment central, $f(x)=1-2x$, ce qui confirme $f(0)=1$.","Parcourir toute la courbe pour ne pas oublier une intersection.","assert 1-2*0==1 and len([-3,0,3])==3",figure='fonction-brisee'),
E('Plusieurs ou aucun antécédent',r"Pour $f(x)=x^2$, déterminer les antécédents de 16, de 0 et de $-1$.",r"Les antécédents de 16 sont $\res{-4\text{ et }4}$. Celui de 0 est seulement $\res0$. Le nombre $-1$ n’a $\res{\text{aucun antécédent}}$, car un carré est positif ou nul.","Résoudre une équation de carré en examinant le signe.","assert set(solve(x*x-16,x))=={-4,4} and solve(x*x,x)==[0] and solveset(x*x+1,x,domain=S.Reals)==S.EmptySet",figure='fonction-carre'),
E('Comparer deux représentations',r"Les fonctions $f(x)=x+2$ et $g(x)=2x-1$ sont représentées. Pour quelle valeur de $x$ leurs images sont-elles égales ? Vérifier par un calcul.",r"Le graphique suggère l’intersection $(3\,;5)$. L’équation $x+2=2x-1$ donne $\res{x=3}$ ; les deux images valent $\res5$. Le calcul valide la lecture.","Relier une intersection à l’égalité des deux images.","assert solve(x+2-(2*x-1),x)==[3] and 3+2==2*3-1==5",figure='fonction-intersection'),
E('Représenter la fonction carré',r"Compléter un tableau de valeurs de $x\mapsto x^2$ pour $x$ égal à $-3$, $-2$, $-1$, $-0{,}5$, 0, 0,5, 1, 2 et 3, puis tracer la courbe dans le repère.",r"Les images sont $\res{9\,;4\,;1\,;0{,}25\,;0\,;0{,}25\,;1\,;4\,;9}$. Deux nombres opposés ont la même image : la courbe est symétrique par rapport à l’axe des ordonnées. On relie les points par une courbe régulière, sans segments, le corrigé la montre en vert.","Calculer les images, placer les points, puis tracer une courbe lisse.","assert [Rational(a)**2 for a in ['-3','-2','-1','-0.5','0','0.5','1','2','3']]==[9,4,1,Rational(1,4),0,Rational(1,4),1,4,9]",figure='carre-trace'),
E('Un réservoir',r"Un réservoir cylindrique de base d’aire 0,8 m$^2$ a une hauteur maximale de 1,5 m. Exprimer son volume en fonction de la hauteur $h$, puis trouver la hauteur correspondant à 600 L.",r"Le volume en m$^3$ vaut $\res{V(h)=0{,}8h}$, avec $0\le h\le1{,}5$. On convertit 600 L en 0,6 m$^3$. L’équation $0{,}8h=0{,}6$ donne $\res{h=0{,}75\text{ m}}$, qui respecte la hauteur maximale.","Choisir les unités avant d’écrire la fonction.","assert Rational('.6')/Rational('.8')==Rational('.75')",figure='cuve-hauteur'),
E('Résoudre graphiquement $x^2=a$',r"À l’aide de la courbe de la fonction carré, lire des valeurs approchées des solutions de $x^2=5$, puis donner leurs valeurs exactes et leurs arrondis au dixième. Combien de solutions ont $x^2=0$ et $x^2=-2$ ?",r"La droite d’équation $y=5$ coupe la parabole en deux points d’abscisses comprises entre 2 et 2,5 en valeur absolue. Les valeurs exactes sont $\res{-\sqrt5\text{ et }\sqrt5}$, soit environ $\res{-2{,}2\text{ et }2{,}2}$ au dixième. L’équation $x^2=0$ a une seule solution, 0 ; $x^2=-2$ n’en a aucune, car la droite $y=-2$ ne rencontre pas la courbe.","Tracer la droite horizontale, puis confirmer par le calcul.","assert set(solve(x*x-5,x))=={-sqrt(5),sqrt(5)} and round(5**.5,1)==2.2 and solveset(x*x+2,x,domain=S.Reals)==S.EmptySet",figure='carre-equation'),
E('Des aires possibles',r"Un rectangle de périmètre 40 cm a un côté de longueur $x$. Exprimer son aire. Quelles sont les entrées possibles ? Donner les images de 3 et de 17.",r"L’autre côté vaut $20-x$. L’aire est $\res{A(x)=x(20-x)}$ cm$^2$, avec $0<x<20$ pour un rectangle non aplati. Les images de 3 et de 17 valent toutes deux $\res{51\text{ cm}^2}$. Une même aire peut donc avoir plusieurs antécédents.","Exprimer l’autre dimension avec la contrainte de périmètre.","assert 3*(20-3)==17*(20-17)==51",figure='rectangle-fonction'),
E('Une lecture de déplacement',r"La courbe donne la distance au point de départ pendant une promenade. Les segments ont pour sommets $(0\,;0)$, $(10\,;600)$, $(15\,;600)$ et $(25\,;0)$, en minutes et mètres. Décrire les phases et calculer la distance totale parcourue sur cet aller-retour rectiligne.",r"On s’éloigne jusqu’à 600 m pendant les dix premières minutes, on reste à cette distance cinq minutes, puis on revient en dix minutes. Dans le modèle rectiligne annoncé, la distance totale est $\res{1200\text{ m}}$. La dernière ordonnée 0 indique le retour au départ, pas un trajet total nul.","Distinguer distance au départ et longueur totale du parcours.","assert 600+600==1200 and 15-10==5",figure='promenade'),
E('Résoudre par un produit nul',r"Pour $f(x)=(x-2)(3x+6)$, déterminer les antécédents de 0. Donner ensuite une image strictement négative.",r"Le produit est nul pour $x-2=0$ ou $3x+6=0$, d’où $\res{2\text{ et }-2}$. Par exemple $f(0)=(-2)\times6=\res{-12}$, strictement négatif. Un exemple suffit pour cette dernière demande d’existence.","Choisir une forme adaptée à l’image recherchée.","assert set(solve((x-2)*(3*x+6),x))=={2,-2} and (0-2)*(3*0+6)==-12")
],reperes=['Vocabulaire, notations et calcul d’images','Tableaux, courbes et antécédents','Fonction carré et équation $x^2=a$','Modèles et domaines de validité'])

chapitre(9,'affines','Fonctions linéaires et affines','2 · Proportionnalité et fonctions',
'Proportionnalité · Droites · Coefficients · Inéquations · Tarifs',
['Reconnaître une fonction linéaire ou affine.','Tracer une droite et déterminer graphiquement ses coefficients.','Comparer des modèles et résoudre des inéquations par le calcul et le graphique.'],['Fonctions, équations et inéquations du premier degré.'],[
r'''\essSection{1}{Deux familles de fonctions}
\begin{definition}Une fonction linéaire est une fonction de la forme $f:x\mapsto ax$. Elle modélise une situation de proportionnalité, de coefficient $a$, et sa représentation est une droite passant par l’origine.\end{definition}
\begin{definition}Une fonction affine est une fonction de la forme $g:x\mapsto ax+b$. Sa représentation est une droite ; $b=g(0)$ est son ordonnée à l’origine. Le coefficient $a$, appelé coefficient directeur ou pente, indique de combien varie l’ordonnée lorsque l’abscisse augmente de 1.\end{definition}
\begin{exemple}Pour $g(x)=2x-3$, le point $(0\,;-3)$ est sur la droite. Quand l’abscisse augmente de 1, l’ordonnée augmente de 2. Les points $(0\,;-3)$ et $(2\,;1)$ suffisent pour tracer la droite.\end{exemple}
\begin{propriete}Un coefficient $a$ positif correspond à une droite montante de gauche à droite, un coefficient négatif à une droite descendante. Si $a=0$, la fonction est constante.\end{propriete}
\begin{attention}« Affine » n’implique pas « proportionnel ». Il faut en plus $b=0$ pour obtenir une fonction linéaire.\end{attention}''',
r'''\essSection{2}{Retrouver une formule et comparer}
\begin{savoirfaire}[Coefficients sur un graphique]Lire $b$ à l’intersection avec l’axe des ordonnées. Pour $a$, partir d’un point de la droite, avancer d’une unité vers la droite et lire la variation verticale, positive en montant, négative en descendant.\end{savoirfaire}
\begin{savoirfaire}[À partir de deux points]Pour deux points de la droite $(x_1\,;y_1)$ et $(x_2\,;y_2)$ avec $x_1\ne x_2$ :
\[a=\frac{y_2-y_1}{x_2-x_1}.\]
Utiliser ensuite $y_1=ax_1+b$ pour retrouver $b$. Une fonction linéaire est déterminée par un seul nombre non nul et son image.\end{savoirfaire}
\begin{savoirfaire}[Inéquations et seuils]Pour comparer deux tarifs, résoudre leur égalité pour repérer le seuil, puis l’inéquation correspondante, par le calcul ou en comparant les positions des droites. Revenir au nombre entier d’unités lorsque la situation l’exige.\end{savoirfaire}
\begin{attention}Une droite verticale ne représente pas une fonction : la même entrée aurait plusieurs images. Une formule affine doit être justifiée par le modèle ou les données.\end{attention}'''],[
E('Reconnaître les formes',r"Parmi $f(x)=-3x$, $g(x)=4x+1$, $h(x)=x^2$ et $k(x)=7$, préciser les fonctions affines et les fonctions linéaires.",r"Les fonctions $\res{f,g,k}$ sont affines, car $k(x)=0x+7$. Seule $\res f$ est linéaire parmi elles. La fonction carré $h$ n’est pas affine.","Comparer les expressions aux définitions.","assert degree(-3*x,x)==1 and degree(4*x+1,x)==1 and degree(x*x,x)==2 and (7!=0)"),
E('Calculer avec une linéaire',r"Pour $f(x)=-2{,}5x$, calculer $f(4)$ et l’antécédent de 15.",r"$f(4)=-2{,}5\times4=\res{-10}$. L’égalité $-2{,}5x=15$ donne $\res{x=-6}$. On divise par un coefficient non nul.","Appliquer puis inverser la multiplication.","assert Rational('-2.5')*4==-10 and 15/Rational('-2.5')==-6"),
E('Lire les coefficients',r"Pour $g(x)=-3x+8$, donner le coefficient directeur, l’ordonnée à l’origine et $g(2)$.",r"Le coefficient directeur est $\res{-3}$, l’ordonnée à l’origine $\res8$ et $g(2)=-6+8=\res2$. La droite descend de gauche à droite.","Relier les coefficients à leur rôle graphique.","assert -3*2+8==2"),
E('Tracer une linéaire',r"Tracer la représentation de $f(x)=1{,}5x$ à l’aide de deux points.",r"La droite passe par l’origine $O(0\,;0)$. Une autre image facile est $f(2)=3$, qui donne $A(2\,;3)$. On trace la droite passant par ces deux points ; le corrigé la montre en vert.","Choisir une entrée donnant une image simple.","assert Rational('1.5')*2==3",figure='affine-trace-lineaire'),
E('Tracer une affine',r"Tracer $g(x)=-x+4$ à l’aide de deux points, puis lire son antécédent de 0.",r"On peut utiliser $(0\,;4)$ et $(4\,;0)$. L’antécédent de 0 est $\res4$, puisque $-4+4=0$. Le graphique et l’équation concordent.","Prendre les intersections avec les axes quand elles sont simples.","assert solve(-x+4,x)==[4]",figure='affine-trace'),
E('Une linéaire à retrouver',r"Une fonction linéaire $f$ vérifie $f(6)=21$. Donner son expression et $f(-2)$.",r"On écrit $f(x)=ax$. Comme $6a=21$, $a=7/2$. Donc $\res{f(x)=3{,}5x}$ et $\res{f(-2)=-7}$. L’information « linéaire » est essentielle pour utiliser un seul point.","Utiliser la forme annoncée avant les données numériques.","assert Rational(21,6)==Rational(7,2) and Rational(7,2)*(-2)==-7"),
E('Deux points, une formule',r"Une fonction affine passe par $A(2\,;1)$ et $B(5\,;10)$. Déterminer son expression.",r"Le coefficient directeur est $(10-1)/(5-2)=3$. On remplace les coordonnées de A dans $y=3x+b$ : $1=6+b$, donc $b=-5$. Ainsi $\res{f(x)=3x-5}$. On contrôle $f(5)=10$.","Calculer le coefficient directeur puis utiliser un point pour la constante.","assert Rational(10-1,5-2)==3 and 3*2-5==1 and 3*5-5==10",figure='affine-deux-points'),
E('Retrouver un tarif',r"Un service affine facture 14 € pour 2 heures et 26 € pour 5 heures. Déterminer le forfait fixe et le prix par heure.",r"L’augmentation de 12 € correspond à trois heures : le prix horaire est $\res{4\text{ €}}$. Pour deux heures, le forfait vaut $14-2\times4=\res{6\text{ €}}$. Le modèle est $P(h)=4h+6$.","Interpréter la variation de prix avant de retrouver le forfait.","assert Rational(26-14,5-2)==4 and 14-2*4==6"),
E('Coefficients lus sur un graphique',r"Déterminer graphiquement les coefficients $a$ et $b$ de la fonction affine représentée, puis donner son expression.",r"La droite coupe l’axe des ordonnées en 3 : $\res{b=3}$. Quand l’abscisse augmente de 1, par exemple de 0 à 1, l’ordonnée passe de 3 à 1 : elle diminue de 2, donc $\res{a=-2}$. La fonction est $\res{f(x)=-2x+3}$ ; la droite descend, ce qui confirme $a<0$.","Lire l’ordonnée à l’origine, puis la variation pour une unité d’abscisse.","assert -2*0+3==3 and -2*1+3==1",figure='affine-lecture'),
E('Comparer par une différence',r"On donne $f(x)=4x-1$ et $g(x)=4x+6$. Comparer leurs images pour toute entrée.",r"La différence $g(x)-f(x)=7$ est toujours positive. Donc $\res{g(x)=f(x)+7}$ pour tout $x$. Les droites ont le même coefficient directeur et des ordonnées à l’origine différentes : elles sont parallèles.","Calculer une différence indépendante de l’entrée.","assert expand((4*x+6)-(4*x-1))==7",figure='affine-paralleles'),
E('Deux abonnements',r"Pour $n$ séances, l’offre A coûte $20+3n$ euros et l’offre B $8+5n$ euros. Déterminer le nombre de séances donnant le même coût, puis résoudre l’inéquation $20+3n<8+5n$ et conclure.",r"L’égalité $20+3n=8+5n$ donne $\res{n=6}$ et un coût de 38 €. L’inéquation équivaut à $12<2n$, soit $n>6$ : A est moins chère $\res{\text{à partir de 7 séances}}$, B l’est pour moins de 6 séances. Les droites se croisent au point $(6\,;38)$.","Résoudre le seuil, puis l’inéquation, et revenir aux nombres entiers.","assert solve(20+3*x-(8+5*x),x)==[6] and solve_univariate_inequality(20+3*x<8+5*x,x,relational=False)==Interval.open(6,oo)",figure='affine-tarifs'),
E('Une vidange à débit constant',r"Une cuve contient 900 L. Elle perd 35 L par minute. Donner le volume restant $V(t)$ avant qu’elle soit vide. Quand reste-t-il 200 L ? Après 30 minutes, la formule peut-elle encore représenter un volume ?",r"Le modèle est $\res{V(t)=900-35t}$. L’égalité $900-35t=200$ donne $\res{t=20\text{ min}}$. À 30 minutes, la formule donne $-150$ L, impossible : le modèle s’arrête quand la cuve est vide, vers 25,7 minutes.","Associer la formule à son domaine physique.","assert solve(900-35*x-200,x)==[20] and 900-35*30<0"),
E('Une vitesse et une inéquation',r"Un mobile se déplace à vitesse constante de 5 m/s. On note $d(t)$ la distance parcourue, en mètres, après $t$ secondes. Exprimer $d$, puis déterminer à partir de quel instant la distance dépasse strictement 120 m. Retrouver le résultat graphiquement.",r"La distance est proportionnelle à la durée : $\res{d(t)=5t}$, fonction linéaire. L’inéquation $5t>120$ équivaut à $\res{t>24}$, car 5 est positif. Graphiquement, la droite $y=5t$ passe au-dessus de la droite horizontale $y=120$ après l’abscisse 24.","Modéliser par une fonction linéaire, puis résoudre l’inéquation.","assert solve_univariate_inequality(5*x>120,x,relational=False)==Interval.open(24,oo)"),
E('Un point suffit-il ?',r"On sait seulement qu’une fonction affine vérifie $f(2)=7$. Peut-on déterminer sa formule ? Donner deux formules différentes possibles.",r"Non : $f(x)=x+5$ et $g(x)=3x+1$ donnent toutes deux 7 en 2, mais diffèrent pour d’autres entrées. Une condition unique ne détermine pas les deux coefficients. Pour une fonction linéaire, $b$ serait déjà imposé à zéro.","Compter les informations et construire deux exemples.","assert 2+5==3*2+1==7 and 0+5!=3*0+1"),
E('Un seuil avec contrainte',r"Deux locations pour $d$ jours entiers coûtent $A(d)=45+12d$ et $B(d)=15+18d$. Un budget de 120 € est prévu. Déterminer la meilleure offre pour 6 jours et le nombre maximal de jours possible dans chaque offre.",r"À 6 jours, A vaut 117 € et B 123 € : seule A respecte le budget. Pour A, $45+12d\le120$ donne $d\le6{,}25$ : le maximum est $\res6$ jours. Pour B, $15+18d\le120$ donne $d\le5{,}83\ldots$ : le maximum est $\res5$ jours. On ne garde que les durées entières.","Résoudre chaque inéquation, puis prendre le plus grand entier solution.","assert 45+12*6<=120<45+12*7 and 15+18*5<=120<15+18*6")
],reperes=['Fonctions linéaires et proportionnalité','Fonctions affines et tracés','Coefficients lus et calculés','Inéquations, comparaisons et seuils'])
